1:import * as v from "valibot";
2:import type { ReadyGraphFunctionCatalog, GraphFunctionCatalogView } from "../product/catalog.js";
3:import type { ModulePublication } from "../gtl/contracts.js";
4:import type { JsonValue } from "../shared/canonical_json.js";
5:import { jsonValueSchema, nonblankSchema, refDigestSchema } from "../shared/public_function_contracts.js";
6:
7:/** This is an output carrier, not an admission or an independent result ledger. */
8:export const ABG_TYPED_TERMINAL_RESULT_SCHEMA = v.strictObject({
9:  kind: v.literal("abg_typed_terminal_result"),
10:  schemaVersion: v.literal("5.0.0"),
11:  result: refDigestSchema,
12:  contract: refDigestSchema,
13:  valueKind: nonblankSchema,
14:  valueDigest: refDigestSchema.entries.digest,
15:  value: jsonValueSchema,
16:  producer: v.strictObject({
17:    runRef: nonblankSchema,
18:    graphCallRef: nonblankSchema,
19:    invocationAdmissionRef: nonblankSchema,
20:    program: refDigestSchema,
21:    graphFunction: refDigestSchema,
22:    executionBasis: refDigestSchema,
23:    cCallRef: nonblankSchema,
24:    resultAdmissionEventRef: nonblankSchema,
25:    judgmentRef: nonblankSchema,
26:    judgmentAdmissionEventRef: nonblankSchema,
27:    terminalRoute: refDigestSchema,
28:  }),
29:  projectionBasis: refDigestSchema,
30:});
31:
32:export type AbgTypedTerminalResult = v.InferOutput<typeof ABG_TYPED_TERMINAL_RESULT_SCHEMA>;
33:
34:export function isAbgTypedTerminalResult(value: unknown): value is AbgTypedTerminalResult {
35:  return v.safeParse(ABG_TYPED_TERMINAL_RESULT_SCHEMA, value).success;
36:}
