38:/** Untrusted, immutable declaration evidence. Only the native projector can
39: * join these bytes to the historical WorkspaceBinding, Catalog and Run. */
40:export interface AbgHistoricalDeclarationProof {
41:  readonly kind: "abg_historical_declaration_proof";
42:  readonly schemaVersion: "5.0.0";
43:  readonly catalog: ReadyGraphFunctionCatalog;
44:  readonly catalogView: GraphFunctionCatalogView;
45:}
46:
47:export const ABG_HISTORICAL_DECLARATION_PROOF_SCHEMA = v.strictObject({
48:  kind: v.literal("abg_historical_declaration_proof"),
49:  schemaVersion: v.literal("5.0.0"),
50:  catalog: jsonValueSchema,
51:  catalogView: jsonValueSchema,
52:}) as unknown as v.GenericSchema<AbgHistoricalDeclarationProof, AbgHistoricalDeclarationProof>;
53:
54:export function isAbgHistoricalDeclarationProof(value: unknown): value is AbgHistoricalDeclarationProof {
55:  return v.safeParse(ABG_HISTORICAL_DECLARATION_PROOF_SCHEMA, value).success;
56:}
57:
58:/** Selection of immutable declaration evidence, never proof of its admission. */
59:export const ABG_HISTORICAL_DECLARATION_REFERENCE_SCHEMA = v.strictObject({
60:  kind: v.literal("abg_historical_declaration_reference"),
61:  schemaVersion: v.literal("5.0.0"),
62:  catalogBasisDigest: refDigestSchema.entries.digest,
63:  readinessBasisDigest: refDigestSchema.entries.digest,
64:  viewDigest: refDigestSchema.entries.digest,
65:});
66:export type AbgHistoricalDeclarationReference = v.InferOutput<typeof ABG_HISTORICAL_DECLARATION_REFERENCE_SCHEMA>;
67:export function isAbgHistoricalDeclarationReference(value: unknown): value is AbgHistoricalDeclarationReference {
68:  return v.safeParse(ABG_HISTORICAL_DECLARATION_REFERENCE_SCHEMA, value).success;
69:}
70:export function constructAbgHistoricalDeclarationReference(proof: AbgHistoricalDeclarationProof): AbgHistoricalDeclarationReference {
71:  if (proof.kind !== "abg_historical_declaration_proof" || proof.schemaVersion !== "5.0.0" ||
72:      proof.catalogView.catalogBasisDigest !== proof.catalog.basisDigest) throw new TypeError("historical declaration basis differs from its View");
73:  return Object.freeze(v.parse(ABG_HISTORICAL_DECLARATION_REFERENCE_SCHEMA, {
74:    kind: "abg_historical_declaration_reference", schemaVersion: "5.0.0",
75:    catalogBasisDigest: proof.catalog.basisDigest, readinessBasisDigest: proof.catalog.readinessBasisDigest,
76:    viewDigest: proof.catalogView.viewDigest,
77:  }));
78:}
