80:/** Stable selection only. The result body and the read prefix remain with ABG. */
81:export const ABG_HISTORICAL_TERMINAL_SELECTION_SCHEMA = v.omit(ABG_TYPED_TERMINAL_RESULT_SCHEMA, ["value", "projectionBasis"]);
82:export type AbgHistoricalTerminalSelection = v.InferOutput<typeof ABG_HISTORICAL_TERMINAL_SELECTION_SCHEMA>;
83:
84:/** One explicit cold declaration dependency, separate from semantic Run input. */
85:const historicalSourceResourceSchema = v.strictObject({
86:  kind: v.literal("abg_historical_graph_call_source_resource"),
87:  schemaVersion: v.literal("5.0.0"),
88:  terminal: ABG_HISTORICAL_TERMINAL_SELECTION_SCHEMA,
89:  input: v.strictObject({ graphFunctionRef: nonblankSchema, contractRef: nonblankSchema }),
90:  declarationProof: ABG_HISTORICAL_DECLARATION_PROOF_SCHEMA,
91:  declarationDependencies: v.optional(v.array(ABG_HISTORICAL_DECLARATION_PROOF_SCHEMA)),
92:});
93:export type AbgHistoricalGraphCallSourceResource = v.InferOutput<typeof historicalSourceResourceSchema>;
94:/** Each immutable basis/View is supplied once, including the primary source. */
95:export function hasUniqueHistoricalDeclarationDependencies(resource: AbgHistoricalGraphCallSourceResource): boolean {
96:  try {
97:    if (resource.declarationDependencies !== undefined && !Array.isArray(resource.declarationDependencies)) return false;
98:    const keys = [resource.declarationProof, ...(resource.declarationDependencies ?? [])].map(proof => {
99:      const ref = constructAbgHistoricalDeclarationReference(proof);
100:      return [ref.catalogBasisDigest, ref.readinessBasisDigest, ref.viewDigest].join(":");
101:    });
102:    return new Set(keys).size === keys.length;
103:  } catch { return false; }
104:}
105:export const ABG_HISTORICAL_GRAPH_CALL_SOURCE_RESOURCE_SCHEMA = v.pipe(historicalSourceResourceSchema,
